<?php require 'config.php';$q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$sort=$_GET['sort']??'featured';$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$sql='SELECT m.*,c.name category_name FROM medicines m JOIN categories c ON c.id=m.category_id WHERE 1=1';$params=[];if($q!==''){$sql.=' AND (m.name LIKE ? OR m.description LIKE ?)';$params[]="%$q%";$params[]="%$q%";}if($cat){$sql.=' AND m.category_id=?';$params[]=$cat;}$sql.=$sort==='low'?' ORDER BY m.price ASC':($sort==='high'?' ORDER BY m.price DESC':($sort==='name'?' ORDER BY m.name':' ORDER BY m.is_featured DESC,m.name'));$s=$pdo->prepare($sql);$s->execute($params);$products=$s->fetchAll();$title='Shop Medicines | MediHome';require 'includes/header.php';?>
<div class="pagehead"><span class="eyebrow">MediHome catalog</span><h1>Shop medicines & essentials</h1><p>Browse healthcare products by name or category.</p></div><form class="filters"><input class="search" name="q" value="<?=e($q)?>" placeholder="Search products..."><select name="category"><option value="0">All categories</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>" <?=$cat===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="sort"><option value="featured">Featured</option><option value="low" <?=$sort==='low'?'selected':''?>>Price low-high</option><option value="high" <?=$sort==='high'?'selected':''?>>Price high-low</option><option value="name" <?=$sort==='name'?'selected':''?>>Name A-Z</option></select><button class="btn">Search</button></form><p><?=count($products)?> product(s) found</p><?php if($products):?><div class="products"><?php foreach($products as $p) require 'includes/card.php';?></div><?php else:?><div class="empty"><h2>No products found</h2><p>Try another search or category.</p><a class="btn" href="/MediHome/medicines.php">Clear filters</a></div><?php endif;?><?php require 'includes/footer.php';?>